// Generated by OrchestKit Claude Plugin
// Created: 2026-08-23

// YAML frontmatter for the Markdown representations this origin serves.
//
// Every Markdown document here is the machine-readable twin of a resource an
// agent may reach from either side: /api/md/* for a docs page, /pricing.md,
// /auth.md and /api-policy.md for the standalone ones. Without a header block
// the Markdown carries no identity of its own. The title is only recoverable by
// parsing the first H1, and nothing in the payload says which URL the document
// is the canonical form of, so an agent that stored the body cannot link it
// back to the page a human would open.
//
// Values are never invented here. Each caller passes the title, description and
// canonical URL its HTML twin already publishes in `metadata`, which is why the
// shared strings live in lib/constants.ts and lib/api-policy.ts rather than
// being retyped per route.

export type MarkdownFrontmatter = {
	title: string;
	/** Omitted from the block when absent rather than filled with a guess. */
	description?: string;
	canonical: string;
};

// YAML double-quoted scalars escape `\` and `"`. Line breaks and tabs are
// folded to a single space first: a description carrying a newline would
// otherwise close the block early and turn the rest of the document into
// frontmatter, which is a parse failure an agent reports as an empty page.
function yamlString(value: string): string {
	const flat = value.replace(/\s+/g, " ").trim();
	return `"${flat.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

/** Render the `---` block on its own, terminated by a newline. */
export function frontmatterBlock(fm: MarkdownFrontmatter): string {
	const lines = ["---", `title: ${yamlString(fm.title)}`];
	if (fm.description) {
		lines.push(`description: ${yamlString(fm.description)}`);
	}
	lines.push(`canonical: ${yamlString(fm.canonical)}`, "---", "");
	return lines.join("\n");
}

/** Prepend a frontmatter block to a Markdown body, blank line between. */
export function withFrontmatter(
	fm: MarkdownFrontmatter,
	body: string,
): string {
	return `${frontmatterBlock(fm)}\n${body}`;
}

// The Vary a response must carry when the SAME URL can answer with either HTML
// or Markdown. Two inputs decide which body a caller gets, so a shared cache has
// to key on both: `Accept` (content negotiation) and `User-Agent` (the AI-crawler
// branch in middleware.ts).
//
// It lives here, next to the other shared Markdown-surface constants, because it
// has to be identical on every response that can serve two representations, and
// it was previously spelled out per handler. `next.config.mjs` also declares it,
// but MEASURED on production 2026-08-23 that declaration does not survive on
// framework-rendered routes: Next calls `res.appendHeader('vary', ...)` with its
// own RSC tokens (base-server.js setVaryHeader) and the configured value is not
// in the result, while every other header from the same config block IS present.
// So the config is necessary but not sufficient, and the value has to be set on
// the response itself.
export const MARKDOWN_VARY = "Accept, Accept-Encoding, User-Agent";
